32: import { AppRoutingModule } from './app/app-routing.module';
33: import { ReactiveFormsModule } from '@angular/forms';
34: import { BedOccupancyModule } from './app/bed-occupancy/bed-occupancy.module';
35: import { SharedModule } from './app/shared/shared.module';
36: import { provideAnimations } from '@angular/platform-browser/animations';
37: import { MatFormFieldModule } from '@angular/material/form-field';
38: import { LoggerModule } from 'ngx-logger';
39: import { AppComponent } from './app/app.component';
40: import { AuthInterceptor } from './app/shared/auth.interceptor';
41: 
42: const appId = 'notification-portal-mf-bed-occupancy';
43: 
44: if (environment.isProduction) {
45:   enableProdMode();
46: }
47: 
48: const lifecycles = singleSpaAngular({
49:   bootstrapFunction: singleSpaProps => {
50:     singleSpaPropsSubject.next(singleSpaProps);
51:     return bootstrapApplication(AppComponent, {
52:       providers: [
53:         provideZoneChangeDetection(),
54:         importProvidersFrom(
55:           RouterModule,
56:           RouterLink,
57:           BrowserModule,
58:           AppRoutingModule,
59:           ReactiveFormsModule,
60:           BedOccupancyModule,
61:           SharedModule,
62:           MatFormFieldModule,
63:           LoggerModule.forRoot(environment.ngxLoggerConfig)
64:         ),
65:         {
66:           provide: HTTP_INTERCEPTORS,
67:           useClass: AuthInterceptor,
68:           multi: true,
69:         },
70:         getSingleSpaExtraProviders(),
71:         provideHttpClient(withInterceptorsFromDi()),
72:         provideAnimations(),
73:         JwtHelperService,
74:         { provide: JWT_OPTIONS, useValue: {} },
75:         provideFormlyCore([
76:           {
77:             extensions: [
78:               {
79:                 name: 'default-placeholder',
80:                 extension: defaultPlaceholderExtension,
81:               },
82:               {
83:                 name: 'default-appearance',
84:                 extension: defaultAppearanceExtension,
85:               },
86:               {
87:                 name: 'aria-required',
88:                 extension: ariaRequiredExtension,
89:               },
90:             ],
91:           },
92:         ]),
93:       ],
94:     });
95:   },
96:   template: '<app-bed-occupancy-root />',
97:   Router,
98:   NgZone,
99:   NavigationStart,
100: });
101: 
102: function init() {
103:   setPublicPath(appId);
104: 
105:   return fetch(environment.pathToEnvironment)
106:     .then(response => response.json())
107:     .then(config => {
108:       environment.bedOccupancyConfig = config;
109: 
110:       if (environment.isProduction) {
111:         enableProdMode();
112:       }
113:     });
114: }
115: 
116: function bootstrapFn(props: AppProps) {
117:   return init().then(() => {
118:     if (typeof lifecycles.bootstrap == 'function') {
119:       return lifecycles.bootstrap(props);
120:     } else {
121:       return lifecycles.bootstrap;
122:     }
123:   });
124: }
125: 
126: export const bootstrap = bootstrapFn;
127: export const mount = lifecycles.mount;
128: export const unmount = lifecycles.unmount;

