467:   private updateAfterPathogenSelection(selectedPathogenCodeDisplay: CodeDisplay, fromHexHexButton = false, fromClipboard = false) {
468:     if (!fromHexHexButton && this.getSelectedPathogenCodeDisplayFromStorage()?.code === selectedPathogenCodeDisplay?.code && !fromClipboard) {
469:       return;
470:     }
471:     this.changeLoadingState(true);
472:     this.resetNotificationCategoryAndSpecimenList();
