119: /**
120:  * Get the current URL from the hash or pathname
121:  * Since we're using HashLocationStrategy, we need to extract the route from the hash
122:  */
123: function getCurrentUrlFromLocation(): string {
124:   // Check if we're using hash-based routing
125:   if (globalThis.location.hash) {
126:     // Extract the path after the # and remove the leading /
127:     const hashPath = globalThis.location.hash.substring(1); // Remove the #
128:     return hashPath.startsWith('/') ? hashPath.substring(1) : hashPath;
129:   }
130:   // Fallback to pathname if no hash
131:   const pathname = globalThis.location.pathname;
132:   return pathname.startsWith('/') ? pathname.substring(1) : pathname;
133: }
